arguments.argument:
if instance_exists(obj_powerout)
{
    if image_index < 0
    and image_speed = -0.8
    {
        image_speed = 0
        image_index = 0
    }
    exit
}
if dir = 2
{
    if global.ventdoor = 1
    and image_index = 0
        image_speed = 0.8
    if image_speed = 0.8 or image_index = 8
    {
        if obj_springbonnie.myroom = 6
            obj_springbonnie.goingback = 1 //Makes animatronic get ready to return to the Dining Area
        else
            obj_springbonnie.goingback = 0
    }
    if image_index > 8.5
    and image_speed = 0.8
    {
        image_speed = 0
        image_index = 8
        global.canopenventdoor = 1
    }
    if global.ventdoor = 0
    and image_index > 0
    {
        if obj_springbonnie.goingback = 0 
        image_speed = -0.8
        else if obj_springbonnie.goingback = 0 
        image_speed = -0.8
        obj_springbonnie.goingback = 0 
        image_speed = -0.8
    }
       if image_index < 0
    and image_speed = -0.8
    {
        image_speed = 0
        image_index = 0
        global.cancloseventdoor = 1

    }
}
